1	type JsonPrimitive = string | number | boolean | null;
2	
3	export type EasyApiQuery = Record<string, JsonPrimitive | undefined>;
4	
5	export type EasyApiRequestOptions = {
6	  query?: EasyApiQuery;
7	  headers?: Record<string, string>;
8	  signal?: AbortSignal;
9	  cache?: RequestCache;
10	  next?: NextFetchRequestConfig;
11	};
12	
13	export type EasyApiBodyOptions = EasyApiRequestOptions & {
14	  body?: unknown;
15	};
16	
17	export type EasyApiErrorBody = {
18	  code: string;
19	  message: string;
20	  details?: unknown;
21	};
22	
23	export type EasyApiErrorEnvelope = {
24	  success: false;
25	  timestamp: string;
26	  error: EasyApiErrorBody;
27	};
28	
29	export type EasyApiResponse<TData, TError = EasyApiErrorBody> =
30	  | { ok: true; status: number; data: TData }
31	  | { ok: false; status: number; error: TError; envelope?: EasyApiErrorEnvelope };
32	
33	type EasyApiSuccessEnvelope<T> = {
34	  success: true;
35	  timestamp: string;
36	  data: T;
37	  message?: string;
38	};
39	
40	const isSuccessEnvelope = (
41	  body: unknown,
42	): body is EasyApiSuccessEnvelope<unknown> =>
43	  typeof body === 'object' &&
44	  body !== null &&
45	  'success' in body &&
46	  (body as { success: unknown }).success === true &&
47	  'data' in body;
48	
49	const isErrorEnvelope = (body: unknown): body is EasyApiErrorEnvelope =>
50	  typeof body === 'object' &&
51	  body !== null &&
52	  'success' in body &&
53	  (body as { success: unknown }).success === false &&
54	  'error' in body;
55	
56	export class EasyApiNetworkError extends Error {
57	  constructor(message: string, options?: { cause?: unknown }) {
58	    super(message, options);
59	    this.name = 'EasyApiNetworkError';
60	  }
61	}
62	
63	const API_KEY_HEADER = 'x-easy-api-key';
64	
65	type EasyApiConfig = { baseUrl: string; apiKey: string };
66	
67	const readConfig = (): EasyApiConfig => {
68	  const baseUrl = process.env.API_BASE_URL;
69	  const apiKey = process.env.API_SECRET_KEY;
70	
71	  if (!baseUrl) {
72	    throw new Error('Missing API_BASE_URL environment variable.');
73	  }
74	  if (!apiKey) {
75	    throw new Error('Missing API_SECRET_KEY environment variable.');
76	  }
77	
78	  return { baseUrl, apiKey };
79	};
80	
81	const joinUrl = (base: string, path: string, query?: EasyApiQuery) => {
82	  const cleanBase = base.replace(/\/+$/, '');
83	  const cleanPath = path.startsWith('/') ? path : `/${path}`;
84	  let url = `${cleanBase}${cleanPath}`;
85	
86	  if (query) {
87	    const params = new URLSearchParams();
88	    for (const [key, value] of Object.entries(query)) {
89	      if (value === undefined || value === null) continue;
90	      params.append(key, String(value));
91	    }
92	    const qs = params.toString();
93	    if (qs) url += `?${qs}`;
94	  }
95	
96	  return url;
97	};
