99	const parseBody = async (response: Response): Promise<unknown> => {
100	  if (
101	    response.status === 204 ||
102	    response.headers.get('content-length') === '0'
103	  ) {
104	    return null;
105	  }
106	
107	  const contentType = response.headers.get('content-type') ?? '';
108	  if (contentType.includes('application/json')) {
109	    return response.json();
110	  }
111	  return response.text();
112	};
113	
114	type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
115	
116	export class EasyApiService {
117	  async request<TData, TError = EasyApiErrorBody>(
118	    method: HttpMethod,
119	    path: string,
120	    options: EasyApiBodyOptions = {},
121	  ): Promise<EasyApiResponse<TData, TError>> {
122	    const { baseUrl, apiKey } = readConfig();
123	    const { query, headers, signal, cache, next, body } = options;
124	
125	    const url = joinUrl(baseUrl, path, query);
126	    const hasBody = body !== undefined;
127	
128	    const init: RequestInit & { next?: NextFetchRequestConfig } = {
129	      method,
130	      headers: {
131	        Accept: 'application/json',
132	        [API_KEY_HEADER]: apiKey,
133	        ...(hasBody ? { 'Content-Type': 'application/json' } : {}),
134	        ...headers,
135	      },
136	      signal,
137	      cache,
138	      next,
139	    };
140	
141	    if (hasBody) {
142	      init.body = JSON.stringify(body);
143	    }
144	
145	    let response: Response;
146	    try {
147	      response = await fetch(url, init);
148	    } catch (error) {
149	      throw new EasyApiNetworkError(
150	        `Easy API request failed: ${method} ${path}`,
151	        { cause: error },
152	      );
153	    }
154	
155	    const parsed = await parseBody(response);
156	
157	    if (response.ok) {
158	      const data = isSuccessEnvelope(parsed) ? parsed.data : parsed;
159	      return { ok: true, status: response.status, data: data as TData };
160	    }
161	
162	    if (isErrorEnvelope(parsed)) {
163	      return {
164	        ok: false,
165	        status: response.status,
166	        error: parsed.error as TError,
167	        envelope: parsed,
168	      };
169	    }
170	    return { ok: false, status: response.status, error: parsed as TError };
171	  }
172	
173	  get<TData, TError = EasyApiErrorBody>(path: string, options?: EasyApiRequestOptions) {
174	    return this.request<TData, TError>('GET', path, options);
175	  }
176	
177	  post<TData, TError = EasyApiErrorBody>(path: string, options?: EasyApiBodyOptions) {
178	    return this.request<TData, TError>('POST', path, options);
179	  }
180	
181	  put<TData, TError = EasyApiErrorBody>(path: string, options?: EasyApiBodyOptions) {
182	    return this.request<TData, TError>('PUT', path, options);
183	  }
184	
185	  patch<TData, TError = EasyApiErrorBody>(path: string, options?: EasyApiBodyOptions) {
186	    return this.request<TData, TError>('PATCH', path, options);
187	  }
188	
189	  delete<TData, TError = EasyApiErrorBody>(path: string, options?: EasyApiBodyOptions) {
190	    return this.request<TData, TError>('DELETE', path, options);
191	  }
192	}
193	
194	export const easyApi = new EasyApiService();
